package za.ac.cput.controller; import org.springframework.web.bind.annotation.*; import za.ac.cput.domain.Role; import za.ac.cput.service.RoleService; import java.util.List; @RestController @RequestMapping("/role") public class RoleController{private final RoleService service; public RoleController(RoleService service){this.service=service;} @PostMapping("/create") public Role create(@RequestBody Role x){return service.create(x);} @GetMapping("/read/{id}") public Role read(@PathVariable String id){return service.read(id);} @PutMapping("/update") public Role update(@RequestBody Role x){return service.update(x);} @DeleteMapping("/delete/{id}") public boolean delete(@PathVariable String id){return service.delete(id);} @GetMapping("/getAll") public List<Role> getAll(){return service.findAll();} }